Definition MLOOP_AT (B : nat) : Prop :=
  forall (i : Z) rax ra sp gp tp t0 t1 t2 a1 a4 a5 a6 a7 s3x s7x s8x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (h : hdrv)
    (j0 j8 jt : list byte) (g : bool),
  isl_ctx m m1 sp (isl_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c pad7 pad2 p0 bs h
          [CB 8 j0; C8 (wz P)] [CB 8 j8] (p0 + i) [CB 24 jt] (ErrCodeCells EC_clear) g ->
  isl_pureA sp P IN E lo shi c p0 bs h ->
  0 <= i -> p0 + i < p0 + Z.of_nat (length bs) -> (Z.to_nat (Z.of_nat (length bs) - i) <= B)%nat ->
  evt asegs (isl_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs h g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0 t1 t2 (wz (E + 16)) (wz E)
              (wz (p0 + i)) a1 (wz (p0 + i + 1)) (wz AL_TAB_IS_TOKEN_CHAR) a4 a5 a6 a7
              (wz IN) s3x (wz (p0 + Z.of_nat (length bs))) (wz p0) (wz i) s7x s8x
              (wz 2147450880) (wz (Z.shiftr IN 3 + 2147450880)) s11x t3 t4 t5 t6)
        F (Z_to_bv 64 0xcf8e4) fc None m1 (seg_rom asegs)).
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.

