(* [comment removed for export] *)
Definition isl_segA_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (h : hdrv) (g : bool),
  a0 = wz P -> a1 = wz IN -> a2 = wz (p0 + Z.of_nat (length bs)) -> a3 = wz E ->
  rw_cells asegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells asegs m IN [C8 (wz p0)] ->
  rw_cells asegs m E (ErrCodeCells EC_clear) ->
  rw_cells asegs m (P + O_PR_USED) [C1 (b8 0)] ->
  rw_cells asegs m (P + O_PR_HDR) (HdrCells h) ->
  bytes_at asegs m p0 bs ->
  AHttpCat m g ->
  stk asegs m lo (bv_unsigned sp) ->
  isl_pureA sp P IN E lo shi c p0 bs h -> mem_inv asegs m ->
  isl_side m P E p0 (Z.of_nat (length bs)) lo shi ->
  evt asegs (isl_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo shi c pad7 pad2 p0 bs h g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_BP_INNER_PARSE_START_LINE) fc None m (seg_rom asegs)).

